import sys, re, os, subprocess

class ReturnException(Exception):
    def __init__(self, val):
        self.val = val

class EvalError(Exception):
    pass

class Env:
    def __init__(self, parent=None):
        self.parent = parent
        self.vars = {}
    def set(self, name, val):
        self.vars[name] = val
    def get(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.get(name)
        raise EvalError(f"Undeclared variable '{name}'")

class Node: pass

class Literal(Node):
    def __init__(self, val): self.val = val
    def eval(self, env): return self.val

class Var(Node):
    def __init__(self, name): self.name = name
    def eval(self, env): return env.get(self.name)

class Let(Node):
    def __init__(self, name, expr): self.name = name; self.expr = expr
    def eval(self, env):
        env.set(self.name, self.expr.eval(env))
        return None

class Assign(Node):
    def __init__(self, name, expr): self.name = name; self.expr = expr
    def eval(self, env):
        # should find where it's declared, but for simple tests just set
        env.set(self.name, self.expr.eval(env))
        return None

class BinOp(Node):
    def __init__(self, op, left, right): self.op = op; self.left = left; self.right = right
    def eval(self, env):
        l = self.left.eval(env)
        r = self.right.eval(env)
        if self.op == '+': return l + r
        if self.op == '-': return l - r
        if self.op == '*': return l * r
        if self.op == '/': return l / r
        if self.op == '==': return l == r
        if self.op == '!=': return l != r
        if self.op == '<': return l < r
        if self.op == '<=': return l <= r
        if self.op == '>': return l > r
        if self.op == '>=': return l >= r
        raise EvalError(f"Unknown op {self.op}")

class Call(Node):
    def __init__(self, func, args): self.func = func; self.args = args
    def eval(self, env):
        f = self.func.eval(env)
        av = [a.eval(env) for a in self.args]
        if hasattr(f, '__call__'): return f(*av)
        raise EvalError("Not a function")

class Block(Node):
    def __init__(self, stmts): self.stmts = stmts
    def eval(self, env):
        res = None
        for s in self.stmts:
            res = s.eval(env)
        return res

class If(Node):
    def __init__(self, cond, t, f): self.cond = cond; self.t = t; self.f = f
    def eval(self, env):
        if self.cond.eval(env): return self.t.eval(env)
        if self.f: return self.f.eval(env)
        return None

class Property(Node):
    def __init__(self, obj, prop): self.obj = obj; self.prop = prop
    def eval(self, env):
        o = self.obj.eval(env)
        if isinstance(o, dict): return o.get(self.prop)
        raise EvalError("Property access on non-dict")

