{"command":"cat << 'EOF' > full_interpreter.py
import sys, re, os, subprocess

class EvalError(Exception): pass
class ReturnException(Exception):
    def __init__(self, val): self.val = val

# Lexer
TOKEN_SPECS = [
    ('COMMENT', r'#.*'),
    ('STRING', r'"(?:\\.|[^"\\])*"'),
    ('NUMBER', r'\d+(\.\d+)?'),
    ('KEYWORD', r'\b(let|if|then|elseif|else|end|while|do|for|in|function|return|and|or|not|true|false|nil)\b'),
    ('IDENT', r'[a-zA-Z_]\w*'),
    ('SYM_2', r'==|!=|<=|>=|\$\{|\@\['),
    ('SYM_1', r'[=+\-*/%<>.|,\(\)\[\]\{\}:]'),
    ('WHITESPACE', r'\s+'),
]
tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in TOKEN_SPECS)

def lex(code):
    pos = 0
    tokens = []
    for mo in re.finditer(tok_regex, code):
        kind = mo.lastgroup
        val = mo.group(kind)
        if kind in ('WHITESPACE', 'COMMENT'): continue
        tokens.append((kind, val))
    return tokens

# Pratt Parser for expressions
class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens): return self.tokens[self.pos]
        return ('EOF', '')

    def get(self):
        t = self.peek()
        if t[0] != 'EOF': self.pos += 1
        return t

    def match(self, val):
        t = self.peek()
        if t[1] == val:
            self.pos += 1
            return True
        return False

    def expect(self, val):
        t = self.get()
        if t[1] != val: raise EvalError(f"Expected {val} got {t[1]}")

    def parse_primary(self):
        t = self.get()
        if t[0] == 'NUMBER':
            return float(t[1]) if '.' in t[1] else int(t[1])
        if t[0] == 'STRING':
            # handle escapes simply
            return t[1][1:-1]
        if t[0] == 'KEYWORD':
            if t[1] == 'true': return True
            if t[1] == 'false': return False
            if t[1] == 'nil': return None
        if t[0] == 'IDENT':
            return {'type': 'Var', 'name': t[1]}
        if t[1] == '(':
            expr = self.parse_expr(0)
            self.expect(')')
            return expr
        if t[1] == '@[': # dict
            d = []
            while not self.match(']'):
                key = self.get()[1]
                self.expect(':')
                val = self.parse_expr(0)
                d.append((key, val))
                self.match(',')
            return {'type': 'Dict', 'items': d}
        if t[1] == '[': # array
            arr = []
            while not self.match(']'):
                arr.append(self.parse_expr(0))
                self.match(',')
            return {'type': 'Array', 'items': arr}
        if t[1] == '{' or t[1] == '${': # cmd
            is_subst = (t[1] == '${')
            cmd = []
            while not self.match('}'):
                # just collect strings/idents for now
                cmd.append(self.get()[1])
            return {'type': 'Cmd', 'subst': is_subst, 'cmd': cmd}
        raise EvalError(f"Unexpected token {t}")

    def parse_expr(self, prec):
        left = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == 'EOF': break

            # handle method calls and property access
            if t[1] == '.':
                self.pos += 1
                prop = self.get()[1]
                left = {'type': 'Prop', 'obj': left, 'prop': prop}
                continue
            if t[1] == '(':
                self.pos += 1
                args = []
                while not self.match(')'):
                    args.append(self.parse_expr(0))
                    self.match(',')
                left = {'type': 'Call', 'func': left, 'args': args}
                continue
            if t[1] == '[':
                self.pos += 1
                idx = self.parse_expr(0)
                self.expect(']')
                left = {'type': 'Index', 'obj': left, 'idx': idx}
                continue

            # binary ops precedence
            prec_map = {'==':1, '!=':1, '<':2, '<=':2, '>':2, '>=':2, '+':3, '-':3, '*':4, '/':4, '%':4}
            p = prec_map.get(t[1], 0)
            if p == 0 or p <= prec: break

            op = self.get()[1]
            right = self.parse_expr(p)
            left = {'type': 'BinOp', 'op': op, 'left': left, 'right': right}

        return left

    def parse_stmt(self):
        t = self.peek()
        if t[1] == 'let':
            self.pos += 1
            name = self.get()[1]
            self.expect('=')
            expr = self.parse_expr(0)
            return {'type': 'Let', 'name': name, 'expr': expr}
        if t[1] == 'if':
            self.pos += 1
            cond = self.parse_expr(0)
            self.expect('then')
            t_body = []
            while self.peek()[1] not in ('else', 'elseif', 'end'):
                t_body.append(self.parse_stmt())
            f_body = None
            nxt = self.get()[1]
            if nxt == 'else':
                f_body = []
                while self.peek()[1] != 'end':
                    f_body.append(self.parse_stmt())
                self.expect('end')
            elif nxt == 'elseif':
                # to handle elseif properly need to nest Ifs, skip for now or implement as nested
                pass # not implemented in quick version
            return {'type': 'If', 'cond': cond, 't': t_body, 'f': f_body}

        # fallback to expression statement or assignment
        expr = self.parse_expr(0)
        if self.match('='):
            val = self.parse_expr(0)
            return {'type': 'Assign', 'target': expr, 'val': val}
        return {'type': 'ExprStmt', 'expr': expr}

def parse(code):
    p = Parser(lex(code))
    stmts = []
    while p.peek()[0] != 'EOF':
        stmts.append(p.parse_stmt())
    return stmts

print(parse('let x = 1 + 2 * 3; if x == 7 then std.print(x) else std.print(0) end'))
EOF
