            self.expect(')')
            return expr
        if t[1] == '@[':
            d = []
            while not self.match(']'):
                key = self.get()[1]
                if key.startswith('"'): key = key[1:-1]
                if self.peek()[1] == ':':
                    self.expect(':')
                    val = self.parse_expr(0)
                    d.append((key, val))
                else:
                    # Just an element? Wait, dicts have to have keys
                    d.append((key, {'type': 'Var', 'name': key}))
                if not self.match(','):
                    self.expect(']')
                    break
            return {'type': 'Dict', 'items': d}
        if t[1] == '[':
            arr = []
            while not self.match(']'):
                arr.append(self.parse_expr(0))
                if not self.match(','):
                    self.expect(']')
                    break
