                if ct[0] == 'STRING': cmd.append(ct[1][1:-1])
                elif ct[1] == '|': cmd.append('|')
                else: cmd.append(ct[1])
            return {'type': 'Cmd', 'subst': is_subst, 'cmd': cmd}
        raise EvalError(f"Unexpected token: {t}")

    def parse_expr(self, prec):
        left = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == 'EOF': break
            if t[1] == '.':
                self.pos += 1
                prop = self.get()[1]
                left = {'type': 'Prop', 'obj': left, 'prop': prop}
                continue
            if t[1] == '(':
                self.pos += 1
                args = []
                while not self.match(')'):
                    args.append(self.parse_expr(0))
                    if not self.match(','):
                        self.expect(')')
