                continue
            if t[1] == '[':
                self.pos += 1
                idx = self.parse_expr(0)
                self.expect(']')
                left = {'type': 'Index', 'obj': left, 'idx': idx}
                continue

            prec_map = {'or':1, 'and':2, '==':3, '!=':3, '<':4, '<=':4, '>':4, '>=':4, '+':5, '-':5, '*':6, '/':6, '%':6}
            p = prec_map.get(t[1], 0)
