                if self.peek()[0] == 'IDENT': raise EvalError("Named function in expression")
                self.expect('(')
                args = []
                while not self.match(')'):
                    args.append(self.get()[1])
                    if not self.match(','):
                        self.expect(')')
                        break
                body = []
                while self.peek()[1] != 'end':
                    body.append(self.parse_stmt())
                self.expect('end')
                return {'type': 'Function', 'args': args, 'body': body}
        if t[0] == 'IDENT': return {'type': 'Var', 'name': t[1]}
        if t[1] == '(':
            expr = self.parse_expr(0)
            self.expect(')')
            return expr
        if t[1] == '@[':
            d = []
            while not self.match(']'):
                key = self.get()[1]
                if key.startswith('"'): key = key[1:-1]
                if self.peek()[1] == ':':
                    self.expect(':')
                    val = self.parse_expr(0)
                    d.append((key, val))
                else:
                    d.append((key, {'type': 'Var', 'name': key}))
                if not self.match(','):
                    self.expect(']')
                    break
            return {'type': 'Dict', 'items': d}
        if t[1] == '[':
            arr = []
            while not self.match(']'):
                arr.append(self.parse_expr(0))
                if not self.match(','):
                    self.expect(']')
                    break
            return {'type': 'Array', 'items': arr}
        if t[1] in ('{', '${'):
            is_subst = (t[1] == '${')
            cmd = []
            while not self.match('}'):
                ct = self.get()
                if ct[0] == 'STRING': cmd.append('"' + ct[1][1:-1] + '"')
                elif ct[1] == '$':
                    nxt = self.get()
                    if nxt[1] == '{':
                        # ${var}
                        v = self.get()[1]
                        self.expect('}')
                        cmd.append('${' + v + '}')
                    else:
                        cmd.append('$' + nxt[1])
                else: cmd.append(ct[1])
            return {'type': 'Cmd', 'subst': is_subst, 'cmd': " ".join(cmd)}
        raise EvalError(f"Unexpected token: {t}")

    def parse_expr(self, prec):
        left = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == 'EOF': break
            if t[1] == '.':
                self.pos += 1
                prop = self.get()[1]
                left = {'type': 'Prop', 'obj': left, 'prop': prop}
                continue
            if t[1] == '(':
                self.pos += 1
                args = []
                while not self.match(')'):
                    args.append(self.parse_expr(0))
                    if not self.match(','):
                        self.expect(')')
                        break
                left = {'type': 'Call', 'func': left, 'args': args}
                continue
            if t[1] == '[':
                self.pos += 1
                idx = self.parse_expr(0)
                self.expect(']')
                left = {'type': 'Index', 'obj': left, 'idx': idx}
                continue

            prec_map = {'or':1, 'and':2, '==':3, '!=':3, '<':4, '<=':4, '>':4, '>=':4, '+':5, '-':5, '*':6, '/':6, '%':6}
            p = prec_map.get(t[1], 0)
            if p == 0 or p <= prec: break

            op = self.get()[1]
            right = self.parse_expr(p)
            left = {'type': 'BinOp', 'op': op, 'left': left, 'right': right}
        return left

    def parse_stmt(self):
        t = self.peek()
        if t[1] == 'function':
            self.pos += 1
            name = self.get()[1]
            self.expect('(')
            args = []
            while not self.match(')'):
                args.append(self.get()[1])
                if not self.match(','):
                    self.expect(')')
                    break
            body = []
            while self.peek()[1] != 'end':
                body.append(self.parse_stmt())
            self.expect('end')
            func = {'type': 'Function', 'args': args, 'body': body}
            return {'type': 'Let', 'name': name, 'expr': func}

        if t[1] == 'let':
            self.pos += 1
            name = self.get()[1]
            self.expect('=')
            expr = self.parse_expr(0)
            return {'type': 'Let', 'name': name, 'expr': expr}

        if t[1] == 'return':
            self.pos += 1
            if self.peek()[1] in ('end', 'elseif', 'else', 'EOF'):
                return {'type': 'Return', 'expr': None}
            expr = self.parse_expr(0)
            return {'type': 'Return', 'expr': expr}

        if t[1] == 'break':
            self.pos += 1
            return {'type': 'Break'}

        if t[1] == 'if':
            self.pos += 1
            cond = self.parse_expr(0)
            self.expect('then')
            t_body = []
            while self.peek()[1] not in ('else', 'elseif', 'end'):
                t_body.append(self.parse_stmt())

            f_body = []
            while self.peek()[1] == 'elseif':
                self.pos += 1
                e_cond = self.parse_expr(0)
                self.expect('then')
                e_body = []
                while self.peek()[1] not in ('else', 'elseif', 'end'):
                    e_body.append(self.parse_stmt())
                f_body.append({'type': 'If', 'cond': e_cond, 't': e_body, 'f': []})

            if self.match('else'):
                while self.peek()[1] != 'end':
                    f_body.append(self.parse_stmt())
            self.expect('end')
            return {'type': 'If', 'cond': cond, 't': t_body, 'f': f_body}

        if t[1] == 'while':
            self.pos += 1
            cond = self.parse_expr(0)
            self.expect('do')
            body = []
            while not self.match('end'):
                body.append(self.parse_stmt())
            return {'type': 'While', 'cond': cond, 'body': body}

        if t[1] == 'for':
            self.pos += 1
            var = self.get()[1]
            self.expect('in')
            iter_expr = self.parse_expr(0)
            self.expect('do')
            body = []
            while not self.match('end'):
                body.append(self.parse_stmt())
            return {'type': 'For', 'var': var, 'iter': iter_expr, 'body': body}

        expr = self.parse_expr(0)
        if self.match('='):
            val = self.parse_expr(0)
            return {'type': 'Assign', 'target': expr, 'val': val}
        return {'type': 'ExprStmt', 'expr': expr}

def parse(code):
    p = Parser(lex(code))
    stmts = []
    while p.peek()[0] != 'EOF':
        stmts.append(p.parse_stmt())
    return stmts

# --- Evaluator ---
class Env:
    def __init__(self, parent=None):
        self.parent = parent
        self.vars = {}
    def set(self, name, val): self.vars[name] = val
    def assign(self, name, val):
        if name in self.vars: self.vars[name] = val
        elif self.parent: self.parent.assign(name, val)
        else: raise EvalError(f"Undeclared variable: {name}")
    def get(self, name):
        if name in self.vars: return self.vars[name]
        if self.parent: return self.parent.get(name)
        raise EvalError(f"Undeclared variable: {name}")

def to_string(v):
    if v is True: return "true"
    if v is False: return "false"
    if v is None: return "nil"
    if isinstance(v, list): return "[ " + ", ".join(to_string(x) for x in v) + " ]"
    if isinstance(v, dict) and 'type' not in v: return "@[ " + ", ".join(f'"{k}": {to_string(val)}' for k,val in v.items()) + " ]"
    if isinstance(v, float) and v.is_integer(): return str(int(v))
    return str(v)

def std_print(*args): print("\t".join(to_string(a) for a in args))
def std_type(v):
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, float): return "float"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict) and v.get('type') != 'Function': return "dict"
    if v is None: return "nil"
    if hasattr(v, '__call__') or (isinstance(v, dict) and v.get('type') == 'Function'): return "function"
    return "unknown"

def std_iter(obj):
    if isinstance(obj, list):
        idx = 0
        def next_fn():
            nonlocal idx
            if idx >= len(obj): return {"finished": True}
            v = obj[idx]
            idx += 1
            return {"finished": False, "value": v}
        return {'type': 'Function', 'py_func': next_fn}
    if isinstance(obj, dict) and obj.get('type') != 'Function':
        items = list(obj.items())
        idx = 0
        def next_fn():
            nonlocal idx
            if idx >= len(items): return {"finished": True}
            k, v = items[idx]
            idx += 1
            return {"finished": False, "value": {"key": k, "value": v}}
        return {'type': 'Function', 'py_func': next_fn}
    raise EvalError("Cannot iter")

def std_len(obj):
    if isinstance(obj, list) or isinstance(obj, str): return len(obj)
    if isinstance(obj, dict) and obj.get('type') != 'Function': return len(obj)
    raise EvalError("Cannot len")

def std_catch(func):
    try:
        return {'type': 'Function', 'py_func': lambda: func()}
    except Exception as e:
        return {"error": str(e)}

def std_push(arr, val):
    if isinstance(arr, list):
        arr.append(val)
        return None
    raise EvalError("push expects array")

def std_pop(arr):
    if isinstance(arr, list):
        return arr.pop() if arr else None
    raise EvalError("pop expects array")

def std_assert(cond, msg="Assertion failed"):
    if not cond: raise EvalError(msg)
    return None

def eval_ast(node, env):
    if isinstance(node, (int, float, bool)) or node is None: return node
    if isinstance(node, dict) and 'type' in node and node['type'] == 'String': return node['val']

    t = node['type']
    if t == 'UnaryOp':
        v = eval_ast(node['expr'], env)
        if node['op'] == '-': return -v
        if node['op'] == 'not': return not v
    if t == 'Break':
        raise BreakException()
    if t == 'Var': return env.get(node['name'])
    if t == 'Let':
        env.set(node['name'], eval_ast(node['expr'], env))
        return None
    if t == 'Assign':
        if node['target']['type'] == 'Var':
            env.assign(node['target']['name'], eval_ast(node['val'], env))
        elif node['target']['type'] == 'Index':
            obj = eval_ast(node['target']['obj'], env)
            idx = eval_ast(node['target']['idx'], env)
            obj[idx] = eval_ast(node['val'], env)
        elif node['target']['type'] == 'Prop':
            obj = eval_ast(node['target']['obj'], env)
            obj[node['target']['prop']] = eval_ast(node['val'], env)
        return None
    if t == 'BinOp':
        l = eval_ast(node['left'], env)
        op = node['op']
        if op == 'and': return l and eval_ast(node['right'], env)
        if op == 'or': return l or eval_ast(node['right'], env)
        r = eval_ast(node['right'], env)
        if op == '+': return l + r
        if op == '-': return l - r
        if op == '*': return l * r
        if op == '/': return l / r
        if op == '%': return l % r
        if op == '==': return l == r
        if op == '!=': return l != r
        if op == '<': return l < r
        if op == '<=': return l <= r
        if op == '>': return l > r
        if op == '>=': return l >= r
    if t == 'Call':
        f = eval_ast(node['func'], env)
        args = [eval_ast(a, env) for a in node['args']]
        if isinstance(f, dict) and f.get('type') == 'Function':
            if 'py_func' in f:
                return f['py_func'](*args)
            new_env = Env(f['env'])
            for i, arg_name in enumerate(f['args']):
                if i < len(args): new_env.set(arg_name, args[i])
            try:
                for s in f['body']: eval_ast(s, new_env)
            except ReturnException as re:
                return re.val
            return None
        raise EvalError("Not callable")
    if t == 'Prop':
        obj = eval_ast(node['obj'], env)
        if isinstance(obj, dict):
            if node['prop'] in obj: return obj[node['prop']]
            return None
        raise EvalError("Prop access on non-dict")
    if t == 'Index':
        obj = eval_ast(node['obj'], env)
        idx = eval_ast(node['idx'], env)
        return obj[idx]
    if t == 'Dict':
        return {k: eval_ast(v, env) for k, v in node['items']}
    if t == 'Array':
        return [eval_ast(v, env) for v in node['items']]
    if t == 'Function':
        return {'type': 'Function', 'args': node['args'], 'body': node['body'], 'env': env}
    if t == 'Return':
        raise ReturnException(eval_ast(node['expr'], env))
    if t == 'If':
        if eval_ast(node['cond'], env):
            for s in node['t']: eval_ast(s, env)
        elif node['f']:
            for s in node['f']: eval_ast(s, env)
        return None
    if t == 'While':
        try:
            while eval_ast(node['cond'], env):
                for s in node['body']: eval_ast(s, env)
        except BreakException: pass
        return None
    if t == 'For':
        iterator = eval_ast(node['iter'], env)
        try:
            while True:
                res = iterator['py_func']() if 'py_func' in iterator else None
                if not res:
                    f_env = Env(iterator['env'])
                    for s in iterator['body']: eval_ast(s, f_env)
                if res.get('finished'): break
                env.set(node['var'], res.get('value'))
                for s in node['body']: eval_ast(s, env)
        except BreakException: pass
        return None
    if t == 'Cmd':
        cmd_str = node['cmd']
        cmd_str = re.sub(r'\$\{([a-zA-Z_]\w*)\}', lambda m: to_string(env.get(m.group(1))), cmd_str)
        cmd_str = re.sub(r'\$([a-zA-Z_]\w*)', lambda m: to_string(env.get(m.group(1))), cmd_str)
        if node['subst']:
            res = subprocess.run(cmd_str, shell=True, capture_output=True, text=True)
            return {"stdout": res.stdout, "stderr": res.stderr}
        else:
            subprocess.run(cmd_str, shell=True)
            return None
    if t == 'ExprStmt':
        return eval_ast(node['expr'], env)

def run(code):
    global_env = Env()
    std = {
        'print': {'type': 'Function', 'py_func': std_print},
        'type': {'type': 'Function', 'py_func': std_type},
        'len': {'type': 'Function', 'py_func': std_len},
        'catch': {'type': 'Function', 'py_func': std_catch},
        'iter': {'type': 'Function', 'py_func': std_iter},
        'push': {'type': 'Function', 'py_func': std_push},
        'pop': {'type': 'Function', 'py_func': std_pop},
        'assert': {'type': 'Function', 'py_func': std_assert},
    }
    global_env.set('std', std)
    try:
        stmts = parse(code)
        for s in stmts: eval_ast(s, global_env)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if not is_check: sys.exit(1)

if __name__ == '__main__':
    run(code)
