        if t[1] == 'not':
            expr = self.parse_expr(10)
            return {'type': 'UnaryOp', 'op': 'not', 'expr': expr}

        if t[0] == 'NUMBER': return float(t[1]) if '.' in t[1] else int(t[1])
        if t[0] == 'STRING':
            s = t[1][1:-1].replace('\\n', '\n').replace('\\t', '\t').replace('\\"', '"').replace('\\\\', '\\')
