            if t[1] == 'true': return True
            if t[1] == 'false': return False
            if t[1] == 'nil': return None
            if t[1] == 'break': return {'type': 'Break'}
            if t[1] == 'function':
                if self.peek()[0] == 'IDENT': raise EvalError("Named function in expression")
