        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens): return self.tokens[self.pos]
        return ('EOF', '')

    def get(self):
        t = self.peek()
        if t[0] != 'EOF': self.pos += 1
        return t

    def match(self, val):
        if self.peek()[1] == val:
            self.pos += 1
            return True
        return False

    def expect(self, val):
        t = self.get()
        if t[1] != val: raise EvalError(f"Expected '{val}', got '{t[1]}'")

    def parse_primary(self):
        t = self.get()
        if t[1] == '-':
            expr = self.parse_expr(10)
            return {'type': 'UnaryOp', 'op': '-', 'expr': expr}
        if t[1] == 'not':
            expr = self.parse_expr(10)
            return {'type': 'UnaryOp', 'op': 'not', 'expr': expr}

        if t[0] == 'NUMBER': return float(t[1]) if '.' in t[1] else int(t[1])
        if t[0] == 'STRING':
            s = t[1][1:-1].replace('\\n', '\n').replace('\\t', '\t').replace('\\"', '"').replace('\\\\', '\\')
            return {'type': 'String', 'val': s}
        if t[0] == 'KEYWORD':
            if t[1] == 'true': return True
            if t[1] == 'false': return False
            if t[1] == 'nil': return None
            if t[1] == 'break': return {'type': 'Break'}
            if t[1] == 'function':
                if self.peek()[0] == 'IDENT': raise EvalError("Named function in expression")
                self.expect('(')
                args = []
                while not self.match(')'):
                    args.append(self.get()[1])
                    if not self.match(','):
                        self.expect(')')
                        break
                body = []
                while self.peek()[1] != 'end':
                    body.append(self.parse_stmt())
                self.expect('end')
                return {'type': 'Function', 'args': args, 'body': body}
        if t[0] == 'IDENT': return {'type': 'Var', 'name': t[1]}
        if t[1] == '(':
            expr = self.parse_expr(0)
            self.expect(')')
            return expr
        if t[1] == '@[':
            d = []
            while not self.match(']'):
                key = self.get()[1]
                if key.startswith('"'): key = key[1:-1]
                if self.peek()[1] == ':':
                    self.expect(':')
                    val = self.parse_expr(0)
                    d.append((key, val))
                else:
                    d.append((key, {'type': 'Var', 'name': key}))
                if not self.match(','):
                    self.expect(']')
                    break
            return {'type': 'Dict', 'items': d}
        if t[1] == '[':
            arr = []
            while not self.match(']'):
                arr.append(self.parse_expr(0))
                if not self.match(','):
                    self.expect(']')
                    break
            return {'type': 'Array', 'items': arr}
        if t[1] in ('{', '${'):
            is_subst = (t[1] == '${')
            cmd = []
            while not self.match('}'):
                ct = self.get()
                if ct[0] == 'STRING': cmd.append('"' + ct[1][1:-1] + '"')
                elif ct[1] == '$':
                    nxt = self.get()
                    if nxt[1] == '{':
                        v = self.get()[1]
                        self.expect('}')
                        cmd.append('${' + v + '}')
                    else:
                        cmd.append('$' + nxt[1])
