    def parse_expr(self, prec):
        left = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == 'EOF': break
            if t[1] == '.':
                self.pos += 1
                prop = self.get()[1]
                left = {'type': 'Prop', 'obj': left, 'prop': prop}
                continue
            if t[1] == '(':
                self.pos += 1
                args = []
                while not self.match(')'):
                    args.append(self.parse_expr(0))
                    if not self.match(','):
                        self.expect(')')
                        break
                left = {'type': 'Call', 'func': left, 'args': args}
                continue
            if t[1] == '[':
                self.pos += 1
                idx = self.parse_expr(0)
                self.expect(']')
                left = {'type': 'Index', 'obj': left, 'idx': idx}
                continue

            prec_map = {'or':1, 'and':2, '==':3, '!=':3, '<':4, '<=':4, '>':4, '>=':4, '+':5, '-':5, '*':6, '/':6, '%':6}
            p = prec_map.get(t[1], 0)
            if p == 0 or p <= prec: break

            op = self.get()[1]
            right = self.parse_expr(p)
            left = {'type': 'BinOp', 'op': op, 'left': left, 'right': right}
        return left

    def parse_stmt(self):
