        if t[1] == 'let':
            self.pos += 1
            name = self.get()[1]
            self.expect('=')
            expr = self.parse_expr(0)
            return {'type': 'Let', 'name': name, 'expr': expr}

        if t[1] == 'return':
            self.pos += 1
            if self.peek()[1] in ('end', 'elseif', 'else', 'EOF'):
                return {'type': 'Return', 'expr': None}
            expr = self.parse_expr(0)
            return {'type': 'Return', 'expr': expr}

        if t[1] == 'break':
            self.pos += 1
            return {'type': 'Break'}

        if t[1] == 'if':
            self.pos += 1
            cond = self.parse_expr(0)
            self.expect('then')
