                    f_body.append(self.parse_stmt())
            self.expect('end')
            return {'type': 'If', 'cond': cond, 't': t_body, 'f': f_body}

        if t[1] == 'while':
            self.pos += 1
            cond = self.parse_expr(0)
            self.expect('do')
            body = []
            while not self.match('end'):
                body.append(self.parse_stmt())
            return {'type': 'While', 'cond': cond, 'body': body}

        if t[1] == 'for':
            self.pos += 1
            var = self.get()[1]
            self.expect('in')
